export function extractCanonicalEaId(playerId: string): string {
  const raw = String(playerId || "").trim();
  const fcMatch = raw.match(/^fc27-p-.+-(\d+)$/);
  if (fcMatch) return fcMatch[1];
  return raw;
}

export function getVerifiedPlayerPenaltyStats(eaOrPlayerId: string): {
  penalties?: number;
  composure?: number;
} {
  const ea = extractCanonicalEaId(eaOrPlayerId);
  const direct = FC27_VERIFIED_PENALTY_RATINGS[ea];
  if (direct) return { penalties: direct[0], composure: direct[1] };
  const num = Number(ea);
  if (Number.isFinite(num) && num > 0) {
    const base = FC27_VERIFIED_PENALTY_RATINGS[String(num & 0xffffff)];
    if (base) return { penalties: base[0], composure: base[1] };
  }
  return {};
}
